3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * When a create request sets {@code sharesHousehold} true and an existing owner already shares this
14	 * owner's last name and address, both are given the same {@code householdId} so the shared household
15	 * is discoverable. The id is a stable identifier derived from the normalized last name and address
16	 * (upper-case hex prefix of their SHA-256), so every member of a household computes the same value.
17	 *
18	 * <p>Last name is compared case-insensitively with collapsed whitespace and address in its normalized
19	 * form (see {@link AddressNormalizer}), matching {@link EnsureUniqueHousehold}, and the id is derived
20	 * from those same normalized values. Runs after {@link BuildOwner} within the create transaction: it sets
21	 * the id on the new owner (persisted by {@link SaveOwner}) and saves any existing members that did not
22	 * yet carry it. A request without {@code sharesHousehold}, or one with no matching owner, is left
23	 * untouched.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
28	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String lastName = normalize(owner.getLastName());
32	        String address = AddressNormalizer.normalize(owner.getAddress());
33	        java.util.List<Owner> household = new java.util.ArrayList<>();
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (normalize(existing.getLastName()).equals(lastName)
36	                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
37	                household.add(existing);
38	            }
39	        }
40	        if (household.isEmpty()) {
41	            return;
42	        }
43	        String householdId = householdId(lastName, address);
44	        owner.setHouseholdId(householdId);
45	        for (Owner member : household) {
46	            if (!householdId.equals(member.getHouseholdId())) {
47	                member.setHouseholdId(householdId);
48	                ownerRepository.save(member);
49	            }
50	        }
51	    }
52	
53	    private static String householdId(String lastName, String address) {
54	        try {
55	            byte[] digest = MessageDigest.getInstance("SHA-256")
56	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
57	            StringBuilder sb = new StringBuilder(16);
58	            for (int i = 0; i < 8; i++) {
59	                sb.append(String.format("%02x", digest[i]));
60	            }
61	            return sb.toString().toUpperCase();
62	        }
63	        catch (NoSuchAlgorithmException e) {
64	            throw new IllegalStateException("SHA-256 unavailable", e);
65	        }
66	    }
67	
68	    private static String normalize(String value) {
69	        if (value == null) {
70	            return "";
71	        }
72	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
73	    }
74	}
