15	 */
16	public class AssignHouseholdSize {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        if (householdId == null) {
21	            owner.setHouseholdSize(1);
22	            return;
23	        }
24	        int count = 1; // the owner being created, not yet saved
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (householdId.equals(existing.getHouseholdId())) {
27	                count++;
28	            }
29	        }
30	        owner.setHouseholdSize(count);
31	    }
